"""Generated by the NL to Flow Diagram Encoder Pipeline."""

print('First Non Repeating Character In a String')

def fnon_repeat(s):
    chars = []
    for character in s:
        chars.append(character)
    counts = []
    for fill_index in range(0, len(chars)):
        counts.append(0)
    i = 0
    while (i < len(chars)):
        j = 0
        while (j < len(chars)):
            if (chars[i] == chars[j]):
                counts[i] = (counts[i] + 1)
            j = (j + 1)
        i = (i + 1)
    i = 0
    while (i < len(chars)):
        if (counts[i] == 1):
            return ((('String = ' + s) + ' Result: ') + chars[i])
        i = (i + 1)
    return ((('String = ' + s) + ' Result: ') + str(None))

print(fnon_repeat('swiss'))

print(fnon_repeat('aabbccd'))

print(fnon_repeat('aabbcc'))
